import csv
from common import *


def main():
    feasibility=json.loads((HERE/'feasibility.json').read_text())
    screen=json.loads((HERE/'screen.json').read_text())
    comparisons=json.loads((HERE/'comparisons.json').read_text())
    validation=json.loads((HERE/'validation.json').read_text())
    def target(name,setting):return next(r for r in feasibility['rows'] if r['image']==name and r['setting']==setting)
    def point(name,preset,variant):return next(r for r in screen['rows'] if r['image']==name and r['preset']==preset and r['variant']==variant)
    def save(name,lines):(HERE/name).write_text('\n'.join(lines)+'\n',encoding='utf-8',newline='\n')
    lines=['# Pass 23 working-target feasibility','','Ordinary downsampling is suboptimal for the tested decoder-equivalent reconstruction, but this does not imply a completed-codec improvement. No image encoding preceded this gate. The control remains pbc31_feature_histogram, source 1c9c4016fdb213d7d16663542d268c7c3df4ed9b; research starts at 0ca503759f6fcc507489dd999a5fe4c848ae2eb7.','','Method: preserve production RGB-to-YCbCr conversion before PIL bicubic downsampling at the 250k cap. Start with that integer target. For each fixed update, reconstruct with production _canvas_to_image (clip, uint8 cast, actual YCbCr-to-RGB), then production bicubic RGB resize with reducing_gap=None. Compute signed RGB source-minus-prediction errors, resize each signed float32 error plane in PIL mode F, and multiply the three low-resolution error planes by a fixed linear RGB-to-YCbCr difference matrix with no offsets. Add the scaled correction, bound total deviation from the ordinary target, round and clip to integer 0..255. This approximate projection is not an established adjoint or exact gradient. The real quantized/color-converted decoder-equivalent output is scored, not a floating-point reconstruction surrogate.','','Fixed before results: conservative step 0.5, one iteration, total per-component deviation cap 8; stronger step 1.0, two iterations, cap 16. No other strengths, sizes or quantizers. Non-downsampled inputs are identity. Alpha/warmup configurations are explicitly outside the research implementation.','','| Image | Working size | Ordinary RGB MSE | Conservative MSE / change | Stronger MSE / change |','| --- | ---: | ---: | ---: | ---: |']
    for name in IMAGES:
        a,b,c=(target(name,setting) for setting in ('ordinary','conservative','stronger'))
        lines.append(f"| {name} | {a['working_size'][0]}x{a['working_size'][1]} | {a['rgb_mse']:.4f} | {b['rgb_mse']:.4f} / {b['mse_change_percent']:+.2f}% | {c['rgb_mse']:.4f} / {c['mse_change_percent']:+.2f}% |")
    lines+=['','Gate: at least two images improve by 5% and none worsens by more than 1%, using one fixed setting. Both settings pass; the predeclared preference selects conservative (Mario64 and Flower exceed 5%, Googlewiki is just under 5%). Only conservative proceeds to encoding. Stronger is retained as a target-only result, not retried as an RD rescue.','','| Image | Setting | Mean / max target change | Target variation change | Edge MSE | Nonedge MSE | Precondition ms | Traced peak MB |','| --- | --- | ---: | ---: | ---: | ---: | ---: | ---: |']
    for name in IMAGES:
        a=target(name,'ordinary')
        for setting in ('ordinary','conservative','stronger'):
            r=target(name,setting)
            lines.append(f"| {name} | {setting} | {r['target_mean_abs_change']:.3f} / {r['target_max_abs_change']} | {100*(r['target_total_variation']/a['target_total_variation']-1):+.2f}% | {r['edge_rgb_mse']:.3f} | {r['nonedge_rgb_mse']:.3f} | {r['preconditioning_seconds']*1000:.2f} | {r['tracemalloc_peak']/1e6:.2f} |")
    lines+=['','Variation is the sum of mean absolute horizontal/vertical differences of the integer working components, a complexity proxy, not entropy or final rate. Edge pixels are the source luminance Sobel magnitude at/above its 90th percentile; exact edge fractions, source-region 4x4 MSE maps and target/output hashes are in feasibility.json. The source masks/envelopes are fixed for all settings.','','Clipping/overshoot diagnostics: outside-range counts refer to proposed bounded working components before color-range clipping, not invalid stored target values. All final targets are bounded uint8-compatible integers. Local-envelope overshoot compares final RGB components on edge pixels to the corresponding original RGB 3x3 neighborhood range; it is an artifact proxy, not a visual ringing verdict.','','| Image | Setting | Outside-range working components by iteration | Deviation cap hits by iteration | Edge envelope mean / max overshoot | Edge overshoot component fraction | Saturated output components |','| --- | --- | ---: | ---: | ---: | ---: | ---: |']
    for r in feasibility['rows']:
        clips='/'.join(str(d['outside_color_range']) for d in r['diagnostics']) or '0'
        caps='/'.join(str(d['deviation_cap_hits']) for d in r['diagnostics']) or '0'
        lines.append(f"| {r['image']} | {r['setting']} | {clips} | {caps} | {r['edge_local_3x3_envelope_overshoot_mean']:.4f} / {r['edge_local_3x3_envelope_overshoot_max']} | {100*r['edge_local_3x3_envelope_overshoot_fraction']:.3f}% | {100*r['output_saturated_component_fraction']:.3f}% |")
    lines+=['','Conservative preconditioning increases working variation on all four images; stronger increases it further and raises the text/graphics overshoot proxy. The photo edge proxy decreases. Clipping is accounted for in every reported RGB MSE. No claim of recovered arbitrary lost high frequencies or absence of visible artifacts.','','Target timings: one warmed untraced operation per setting/image, excluding source load, ordinary prepare and external diagnostics. The update timer includes decoder-equivalent prediction and all signed projections. A separate repeated call enables tracemalloc; these peaks include NumPy/Python registered allocations, not all native PIL storage or total process working memory. At Cat/Flower source size, one float32 source error plane is 34.10 MB and the full uint8 RGB source/output is 25.58 MB; the target is about 3.00 MB int32. Traced conservative temporary peaks are about 196.5 MB, stronger 205.5 MB. They are measured temporary costs, not a low-memory implementation claim. No optimization rescue was attempted.','','The target-only gate establishes useful representational headroom for this bounded update rule. Its 0.44-0.50 s photographic cost is already substantial; completed-file encodes measure whether any RD gain justifies it.']
    save('PBC_WORKING_TARGET_FEASIBILITY.md',lines)
    lines=['# Pass 23 decoder-aware completed-file results','','The conservative target adjustment fails the frozen progression gate. It yields one same-preset strict RD win (Cat Quality), several HQ quality/rate trades, and two Quality points dominated by their unchanged controls. No Monet/Eiffel extension, three-repeat timing campaign, classifier, dual encode or parameter rescue followed.','','Implementation: research_pass23.encoder.DecoderAwarePBC overrides only prepare. It calls the original preparation, adjusts the target once, then updates arr(uint8) and target(int32) together. Initialization means, downsample initialization, learned features, patch search/channel scores and gain calculations therefore read the adjusted data. Original RGB orig_compare, dimensions, warmup metadata, model, release RNG, patch syntax, LZMA and decoder remain unchanged. Internal MSE is enabled and independently matches the true source RGB score. There are no global production monkeypatches.','','One deterministic completed encode/decode per image/preset/variant after tiny Q/HQ warmups; alternating pair order. Intel i9-12900H logical P-core 12, one numerical thread, Python 3.11.16/NumPy 2.4.6/Numba 0.68.0/Pillow 11.3.0. Encode includes preparation, preconditioning, patches, entropy and internal original-source MSE. Full ordinary v0 decode is timed independently. Input loading, extra diagnostic prepare, hashing, file I/O, parsing and external scoring are outside timers. Sixteen measured full-image encodes, no 100-case matrix. Timings are one-pass feasibility observations, not repeated speed claims or HF timings.','','| Image | Preset | Baseline bytes | Candidate bytes | Baseline RGB MSE | Candidate RGB MSE | Encode change |','| --- | --- | ---: | ---: | ---: | ---: | ---: |']
    for r in screen['comparisons']:
        a=point(r['image'],r['preset'],'ordinary');b=point(r['image'],r['preset'],'candidate')
        lines.append(f"| {r['image']} | {r['preset']} | {a['bytes']:,} | {b['bytes']:,} | {a['rgb_mse']:.4f} | {b['rgb_mse']:.4f} | {r['encode_change_percent']:+.2f}% |")
    lines+=['','| Image / preset | Final bpp ordinary -> candidate | Rate change | RGB MSE change | Encode s ordinary -> candidate | Decode ms ordinary -> candidate |','| --- | ---: | ---: | ---: | ---: | ---: |']
    for r in screen['comparisons']:
        a=point(r['image'],r['preset'],'ordinary');b=point(r['image'],r['preset'],'candidate')
        lines.append(f"| {r['image']} / {r['preset']} | {a['bpp']:.5f} -> {b['bpp']:.5f} | {r['rate_change_percent']:+.2f}% | {r['mse_change_percent']:+.2f}% | {a['encode_seconds']:.4f} -> {b['encode_seconds']:.4f} | {a['decode_seconds']*1000:.2f} -> {b['decode_seconds']*1000:.2f} |")
    lines+=['','Bpp is complete post-LZMA bytes divided by original pixel count. Raw patch savings do not imply final file savings: Mario64 Quality raw bytes fall 172,902 ->160,486 while final bytes rise 64,809 ->71,219. Both raw and wrapped bytes are retained below and in screen.json.','','| Image / preset | Raw bytes ordinary -> candidate | Total patches ordinary -> candidate | Working target MSE ordinary -> candidate | Ordinary-target MSE of candidate canvas |','| --- | ---: | ---: | ---: | ---: |']
    for r in screen['comparisons']:
        a=point(r['image'],r['preset'],'ordinary');b=point(r['image'],r['preset'],'candidate')
        lines.append(f"| {r['image']} / {r['preset']} | {a['raw_bytes']:,} -> {b['raw_bytes']:,} | {a['total_patches']} -> {b['total_patches']} | {a['working_target_mse']:.3f} -> {b['working_target_mse']:.3f} | {b['ordinary_working_target_mse']:.3f} |")
    lines+=['','Working MSE is mean squared YCbCr component error against the clipped decoded working canvas. Candidate working-target MSE uses its adjusted target; it is not original-resolution RGB MSE and the target references differ. The last column instead uses the same ordinary target. Unclipped canvas error, initialization/iterative counts and grid-cell counts by bit depth are retained in screen.json. Total patch counts include 3 initialization patches.','','Actual effective palette-bit distribution, all serialized patches including initialization (bitcount:patch count):','','| Image / preset | Ordinary | Candidate |','| --- | --- | --- |']
    for r in screen['comparisons']:
        fields=[]
        for variant in ('ordinary','candidate'):
            a=point(r['image'],r['preset'],variant)
            fields.append(', '.join(f'{k}:{v}' for k,v in sorted(a['effective_bits_patch_counts'].items(),key=lambda x:int(x[0]))))
        lines.append(f"| {r['image']} / {r['preset']} | {fields[0]} | {fields[1]} |")
    lines+=['','Stronger ordinary comparisons: all saved Q/HQ, HQ p10, Quality p10 bases, existing targeted budgets, and Googlewiki HQ500k were independently decoded, hash/MSE checked, and reused without new control encodes. The candidate always keeps 250k. Current ordinary screen streams exactly reproduce Pass17 hashes. The verified controls and provenance are in comparisons.json.','','| Image / preset | Best actual ordinary within 5% bytes | Signed rate gap | Candidate MSE change |','| --- | --- | ---: | ---: |']
    for r in comparisons['rows']:
        near=r['strongest_actual_within5pct']
        lines.append(f"| {r['image']} / {r['preset']} | {near['preset'] if near else 'none'} | {format(near['signed_rate_gap_percent'],'+.2f')+'%' if near else '-'} | {format(near['mse_change_percent'],'+.2f')+'%' if near else '-'} |")
    lines+=['','Nearby does not mean equal rate. Mario64 Quality looks favorable against inefficient HQ p10 but is actually dominated by ordinary default Quality (fewer bytes, lower MSE); Googlewiki Quality is also dominated by its default Quality control. Flower Quality saves 1.81% rate versus HQ p10 but worsens MSE 1.02%. The three HQ candidates improve MSE roughly 6.1-6.7% versus default HQ at 1.5-3.3% extra rate; that is useful narrow evidence, not exact matched-rate proof.','','Conservative matched-rate estimates use the lowest interpolated ordinary MSE among all valid measured bracketing chords, never extrapolate. These are estimates across sparse operating points, not achievable equal-rate files. Googlewiki includes the stronger 500k point; its broad bracket is especially uncertain.','','| Image / preset | Ordinary bracket | Estimated ordinary MSE | Candidate MSE | Estimated MSE change |','| --- | --- | ---: | ---: | ---: |']
    for r in comparisons['rows']:
        b=r['ordinary_rate_bracket']
        if b:lines.append(f"| {r['image']} / {r['preset']} | {b['a']} -> {b['b']} | {b['value']:.4f} | {r['rgb_mse']:.4f} | {r['interpolated_matched_rate_mse_change_percent']:+.2f}% |")
        else:lines.append(f"| {r['image']} / {r['preset']} | no measured bracket | - | {r['rgb_mse']:.4f} | - |")
    lines+=['','Only Cat Quality has a favorable bracket estimate (-4.65%). Googlewiki HQ improves the same default HQ point, yet does not beat the conservative quality-to-500k ordinary chord (+28.39% estimated MSE); neither an actual domination claim nor a reliable continuous frontier follows from that interpolation. Mario64/Cat/Flower HQ rates exceed the measured ordinary maxima, so no equal-rate estimate is invented.','','Screen gate: 3 useful points across 3 images (at least 3% MSE reduction at no more than 5% extra rate), but only 1 same-preset strict RD win, and mean per-point final-rate increase 9.84%. Required at least 2 strict wins and mean rate increase at most 5%; gate fails. Maximum MSE worsening is 1.81%, so catastrophic quality regression is not the failure reason. Substantial rate and encoder costs prevent general adoption.','','Interpretation: ideal preconditioning helps all four images, but the adjusted working images have higher spatial variation and changed patch trajectories. Googlewiki Quality fitting error rises 31.52 ->51.24 against its own target, and 31.52 ->44.32 against the original target; Mario64 Quality likewise fits worse. Flower Quality uses fewer patches yet 40.0% more final bytes. Cat Quality is a real isolated RD success, while Cat HQ spends 18.9% more final bytes for 4.2% MSE improvement. These observations support complexity/representation and trajectory limitations; this pass does not separately identify model-policy mismatch versus quantization/search as the causal factor.','','The 0.44-0.50 s conservative photographic preprocessing appears in complete encode overhead of roughly 54-59%, exceeding the 10% preference. Graphics overhead is about 7-16% in one-pass observations. Actual decode changes span roughly -6.2% to +8.1%, reflecting different payload/patch paths plus timing noise. There is no added decoder operation, but exact equal decode times are not claimed.','','Validation: all 16 streams pass unchanged ordinary v0 decoding, file/pixel hashes, repeat decoding, original RGB dimensions/MSE and enabled internal MSE agreement. Twelve deterministic preparation/reconstruction fixtures cover RGB/YCbCr, identity/downsampled,1x1 and odd dimensions, consistent arr/target and bounded corrections. Alpha/warmup unsupported configurations reject. Four fresh subprocesses decode candidate text/photo files with policy loading forbidden, through the practical and immutable PBC3.0 release decoders. No production source, public default, model, decoder or enhancement container changes.']
    save('PBC_DECODER_AWARE_RD_RESULTS.md',lines)
    lines=['# Pass 23 summary','','Stop after the four-image Quality/HQ screen. The target-only hypothesis succeeds; the tested encoder-only method fails the completed-file progression gate. No additional images or repeated timing campaign.','','1. Ordinary YCbCr downsampling is suboptimal for these tested quantized decoder-equivalent reconstructions; this is not a universal optimality claim. Conservative back-projection reduces target-only MSE by 4.95% Googlewiki, 7.73% Mario64, 3.04% Cat, 11.26% Flower. The stronger predeclared target-only setting improves 7.71%, 13.26%, 5.97%, 19.39% respectively.','2. Conservative step 0.5/one iteration/8-level total correction cap was selected by the frozen rule. The research prepare subclass changes only arr/target, preserves true-source orig_compare, and successfully produces ordinary v0 files. Stronger was not encoded as a rescue.','3. Completed-file behavior is mixed: Cat Quality improves final size 9.33% and RGB MSE 2.41%; Googlewiki/Mario64/Flower HQ improve MSE 6.09%/6.65%/6.40% for 3.34%/1.47%/1.96% more bytes. Googlewiki and Mario64 Quality worsen both size and MSE; Flower Quality costs 40.04% more bytes for 10.68% lower MSE. Cat HQ costs 18.94% more for 4.21% lower MSE.','4. No universal 5-10% matched-rate improvement is established. Cat Quality has an estimated 4.65% matched-rate MSE gain. Three Quality estimates regress; Googlewiki HQ also loses against the conservative bracket including the saved stronger 500k control. Other HQ points have no measured enclosing ordinary bracket; their close-rate gaps remain explicit. Estimates are not achievable equal-rate files.','5. One strict same-preset RD win and 9.84% mean rate increase fail the frozen gate. The target-only MSE signal does not predict which preset will yield a good compressed result. No classifier or dual-encode activation rule is justified by four images; no activation was built.','6. Full one-pass encoding overhead is 7.1-15.6% on graphics, 53.8-58.9% on photos. Preconditioning alone costs about 80-90 ms graphics and 437-505 ms photos. This is substantial relative to ordinary encoding. Decoder syntax/computation is unchanged; actual payload-dependent decode times were measured, with one-pass variation explicitly retained.','7. All 16 actual files preserve v0 compatibility and correct original-source internal/external MSE; 12 prepare fixtures and four model-free practical/release subprocess decodes pass. Source/input/model/config/stream/pixel hashes, real bit-depth counts and full/raw byte sizes are recorded.','8. Monet/Eiffel generalization is untested because the initial completed-file gate failed. The stronger target setting, content classifier, large sharpening search, per-patch RGB rescoring, broad 100-case benchmark and another encoder optimization were not attempted.','9. The observed limitation is converting a better ideal target into efficient learned-patch/LZMA representation, plus full-source projection cost. Target variation and changed fitting/patch counts support this interpretation; causal attribution to learned policy alone is not established.','10. Keep the isolated Cat Quality and close-rate HQ leads as evidence, but do not broaden or integrate this method. A distinct future direction is native residual rate allocation using measured patch gain and completed-stream marginal cost, rather than further target sharpening or model retraining. No followup was launched.','','Reproduction: same Python 3.11 research environment and ../research_pass17/requirements.txt, restored hpt_data, saved ordinary Pass17 controls and the Pass18 Googlewiki 500k control matching their recorded hashes. Run from repository root:','','```','research_pass16/.venv/Scripts/python.exe research_pass23/feasibility.py','research_pass16/.venv/Scripts/python.exe research_pass23/screen.py','research_pass16/.venv/Scripts/python.exe research_pass23/compare.py','research_pass16/.venv/Scripts/python.exe research_pass23/validate.py','research_pass16/.venv/Scripts/python.exe research_pass23/report.py','```','','screen.py enforces the Phase A selection. screen.py --extend enforces the failed C gate and was not run. The reproduction commands regenerate only ignored streams and this pass measurements/reports; they do not change production. Raw numerical rows are in feasibility.json/screen.json/comparisons.json; reports separate actual files, near-rate observations and interpolated estimates. Full config/model identity is recorded per case.','','Practical codec, v0, model, frozen Pass17/21/22, HF and staging remain unchanged. ZIP SHA256: 08855cb3369000fd50d38fbb41d65920899998d366812c04519302383d873591. Focused research-only commit/push to research/experiments is authorized; the final verified GitHub commit/HEAD is supplied in the chat handoff. No protected branch, release/tag, deployment or staging changes.']
    save('PBC_PASS23_SUMMARY.md',lines)
    fields=['image','preset','variant','bytes','raw_bytes','bpp','rgb_mse','working_target_mse','ordinary_working_target_mse','total_patches','encode_seconds','decode_seconds','input_sha256','stream_sha256','pixels_sha256','target_sha256']
    with (HERE/'files.csv').open('w',newline='',encoding='utf-8') as file:
        writer=csv.DictWriter(file,fieldnames=fields,extrasaction='ignore',lineterminator='\n');writer.writeheader();writer.writerows(screen['rows'])
    result=meta();result.update(evidence_sha256={p.name:sha(p.read_bytes()) for p in HERE.iterdir() if p.suffix in ('.json','.csv') and p.name!='provenance.json'},prior_control_evidence_sha256=comparisons['input_evidence_sha256'],selected_parameters=SETTINGS[feasibility['chosen']],phase_a_passed=True,phase_c_passed=False,extension_executed=False,repeat_timing_executed=False,full_image_encode_count=16,staged_zip_sha256_unchanged='08855cb3369000fd50d38fbb41d65920899998d366812c04519302383d873591')
    write('provenance.json',result)
    print('reports written; target feasibility passes, completed-file RD gate fails; stopped before extension/timing repeats',flush=True)


if __name__=='__main__':main()
